"""Independent source-bound comparison of the exact officer branches.

The result describes a recorded contrast. It does not decide the statute.
"""

import argparse
import hashlib
import json
from pathlib import Path

from officer_direction import PREFIX


PAIRS = {
    "officer_control_exception": (PREFIX + "officer_controls_go", PREFIX + "officer_present_inactive"),
    "officer_direction": (PREFIX + "officer_controls_go", PREFIX + "officer_controls_hold"),
}
FIXED = ("native_map_id", "intersection_id", "junction_source", "ego_route_source",
         "sign_inventory_source", "other_entrance_source", "highway_status_source",
         "non_through_highway", "ego_entrance_device", "other_entrance_device",
         "intersection_polygon_xy_m")


def _sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _read(path):
    if not path.is_file():
        raise ValueError("Missing comparison source: " + str(path))
    return json.loads(path.read_text())


def _attempt(root, expected):
    root = Path(root)
    report = _read(root / "analysis.json")
    if report.get("format") != "worker-c157964-subsection-2-saved-analysis" or report.get("case_id") != expected:
        raise ValueError("Comparison exact case ID differs")
    if report.get("legal_conclusion") != "unresolved" or report.get("physical_acceptance_claimed") is not False:
        raise ValueError("Comparison cannot pre-decide legal or physical outcome")
    context = _read(root / "officer_context.json")
    history_path = root / "officer_history.jsonl"
    if context.get("case_id") != expected or not history_path.is_file():
        raise ValueError("Missing exact original officer context/history")
    hashes = report.get("source_sha256", {})
    if hashes.get("officer_context.json") != _sha(root / "officer_context.json") or hashes.get("officer_history.jsonl") != _sha(history_path):
        raise ValueError("Comparison original source hash changed")
    rows = [json.loads(line) for line in history_path.read_text().splitlines() if line.strip()]
    observed = report.get("source_report", {})
    samples = observed.get("samples")
    if not rows or not isinstance(samples, list) or len(rows) != len(samples):
        raise ValueError("Comparison original frame interval incomplete")
    for row, sample in zip(rows, samples):
        if (row.get("frame") != sample.get("frame") or row.get("time_s") != sample.get("time_s")
                or row.get("officer_direction_observed") != sample.get("direction")
                or row.get("traffic_control_observed") is not sample.get("traffic_control_observed")
                or not row.get("direction_frame_source") or not row.get("other_frame_source")):
            raise ValueError("Comparison saved observation differs from original frame")
    return context, observed, hashes


def audit(comparison_id, first_root, second_root):
    if comparison_id not in PAIRS:
        raise ValueError("Unknown exact comparison")
    first_id, second_id = PAIRS[comparison_id]
    first_context, first, first_hashes = _attempt(first_root, first_id)
    second_context, second, second_hashes = _attempt(second_root, second_id)
    if any(first_context.get(key) != second_context.get(key) for key in FIXED):
        raise ValueError("Comparison fixed site and sign context differs")
    left = first.get("first_ego_entry")
    right = second.get("first_ego_entry") or second.get("first_hold_observation")
    if not left or not right:
        raise ValueError("Comparison lacks source-observed entry or hold")
    if comparison_id == "officer_control_exception":
        if (left.get("traffic_control_observed"), right.get("traffic_control_observed")) != (True, False):
            raise ValueError("Original officer-control contrast missing")
        if (left.get("officer_direction_observed"), right.get("officer_direction_observed")) != ("go", "none"):
            raise ValueError("Original go versus inactive direction contrast missing")
    else:
        if (left.get("traffic_control_observed"), right.get("traffic_control_observed")) != (True, True):
            raise ValueError("Direction comparison lacks active control")
        if (left.get("officer_direction_observed"), right.get("officer_direction_observed")) != ("go", "stop"):
            raise ValueError("Original go versus hold direction contrast missing")
    return {"format": "worker-c157964-subsection-2-comparison-audit",
            "comparison_id": comparison_id, "case_ids": [first_id, second_id],
            "fixed_context": {key: first_context[key] for key in FIXED},
            "source_hashes": {"first": first_hashes, "second": second_hashes},
            "observed": {"first": left, "second": right},
            "comparison_passed": True, "physical_acceptance_claimed": False,
            "legal_conclusion": "unresolved"}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--comparison", choices=sorted(PAIRS), required=True)
    parser.add_argument("--first", type=Path, required=True)
    parser.add_argument("--second", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    result = audit(args.comparison, args.first, args.second)
    args.output.write_text(json.dumps(result, indent=2) + "\n")


if __name__ == "__main__":
    main()

"""Four original lossless Native camera streams for C157964 subsection 2 officer review."""

from pathlib import Path
import subprocess

CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")
CAMERA_SIZES = {"overview": (1920, 1080), "approach": (1280, 720),
                "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


class FourCameraEncoder:
    """Retain four original BGRA sensor streams in lossless FFV1 containers."""

    def __init__(self, root, sizes=None, fps=20):
        self.root = Path(root).resolve()
        repo = Path(__file__).resolve().parents[2]
        if self.root.is_relative_to(repo) and not self.root.is_relative_to(repo / ".runtime-work"):
            raise ValueError("Original camera media must stay under .runtime-work")
        self.sizes = dict(CAMERA_SIZES if sizes is None else sizes)
        if set(self.sizes) != set(CAMERAS) or type(fps) is not int or fps <= 0:
            raise ValueError("Four named camera dimensions and integer rate required")
        if any(not isinstance(size, (tuple, list)) or len(size) != 2 or
               any(type(v) is not int or v <= 0 for v in size)
               for size in self.sizes.values()):
            raise ValueError("Invalid camera dimensions")
        self.fps = fps
        self.processes = {}
        self.count = 0

    def __enter__(self):
        self.root.mkdir(parents=True, exist_ok=True)
        if any((self.root / (name + ".mkv")).exists() for name in CAMERAS):
            raise ValueError("Original camera video already exists")
        try:
            for name in CAMERAS:
                width, height = self.sizes[name]
                command = ["ffmpeg", "-hide_banner", "-loglevel", "error", "-y",
                           "-f", "rawvideo", "-pixel_format", "bgra", "-video_size",
                           f"{width}x{height}", "-framerate", str(self.fps),
                           "-i", "pipe:0", "-an", "-c:v", "ffv1", "-level", "3",
                           "-pix_fmt", "bgr0", str(self.root / (name + ".mkv"))]
                self.processes[name] = subprocess.Popen(command, stdin=subprocess.PIPE,
                                                        stdout=subprocess.DEVNULL,
                                                        stderr=subprocess.PIPE)
        except Exception:
            self._finish(abort=True)
            raise
        return self

    def validate_packets(self, packets):
        if set(packets) != set(CAMERAS):
            raise ValueError("Four original camera packets required")
        for name in CAMERAS:
            packet = packets[name]
            width, height = self.sizes[name]
            if (packet.width, packet.height) != (width, height) or len(packet.raw_data) != width * height * 4:
                raise ValueError("Camera pixels differ from capture profile: " + name)

    def add_packets(self, packets):
        self.validate_packets(packets)
        for name in CAMERAS:
            self.processes[name].stdin.write(packets[name].raw_data)
        self.count += 1

    def _finish(self, abort=False):
        failures = []
        self.exit_codes = {}
        processes, self.processes = self.processes, {}
        for name, process in processes.items():
            if abort:
                if process.poll() is None:
                    process.kill()
            process.stdin.close()
            stderr = process.stderr.read().decode("utf-8", errors="replace")
            process.stderr.close()
            code = process.wait()
            self.exit_codes[name] = code
            if not abort and (code != 0 or not (self.root / (name + ".mkv")).is_file()):
                failures.append(name + ": " + stderr[-400:])
        if failures:
            raise ValueError("Four-camera FFV1 encoding failed: " + "; ".join(failures))

    def __exit__(self, kind, value, trace):
        self._finish(abort=kind is not None)
        return False

"""Four synchronized original Native sensor streams for subsection 2 capture."""

from queue import Empty, Queue

from officer_camera import CAMERAS, FourCameraEncoder


class CameraMedia:
    def __init__(self, world, root, blueprints, mounts, actors, *, sizes=None,
                 timeout_s=10, encoder_factory=FourCameraEncoder):
        if set(blueprints) != set(CAMERAS) or set(mounts) != set(CAMERAS):
            raise ValueError("Four camera blueprints and mounts required")
        if not isinstance(actors, dict) or "ego" not in actors:
            raise ValueError("Native camera actor map required")
        if type(timeout_s) not in (int, float) or timeout_s <= 0:
            raise ValueError("Positive camera wait timeout required")
        self.world, self.root, self.blueprints = world, root, blueprints
        self.mounts, self.actors = mounts, actors
        self.sizes, self.timeout_s = sizes, timeout_s
        self.encoder_factory = encoder_factory
        self.encoder = None
        self.sensors = {}
        self.queues = {}

    def __enter__(self):
        try:
            for name in CAMERAS:
                mount = self.mounts[name]
                if (not isinstance(mount, dict) or set(mount) != {"transform", "attach_to"} or
                        mount["attach_to"] not in (None, "ego", "other", "officer")):
                    raise ValueError("Invalid original camera mount: " + name)
                parent = self.actors.get(mount["attach_to"])
                if mount["attach_to"] is not None and parent is None:
                    raise ValueError("Camera attachment actor missing: " + name)
                kwargs = {} if parent is None else {"attach_to": parent}
                sensor = self.world.spawn_actor(self.blueprints[name], mount["transform"], **kwargs)
                if sensor is None:
                    raise ValueError("Native camera spawn failed: " + name)
                self.sensors[name] = sensor
                self.queues[name] = Queue()
                sensor.listen(self.queues[name].put)
            self.encoder = self.encoder_factory(self.root, sizes=self.sizes)
            self.encoder.__enter__()
            return self
        except BaseException:
            self._close(abort=True)
            raise

    def readback(self, native_frame):
        if type(native_frame) is not int or self.encoder is None:
            raise ValueError("Native camera frame or media writer missing")
        packets = {}
        for name in CAMERAS:
            try:
                packet = self.queues[name].get(timeout=self.timeout_s)
            except Empty as exc:
                raise ValueError("Original camera packet missing: " + name) from exc
            if getattr(packet, "frame", None) != native_frame:
                raise ValueError("Original camera packet frame mismatch: " + name)
            packets[name] = packet
        self.encoder.validate_packets(packets)
        video_index = self.encoder.count
        self.encoder.add_packets(packets)
        return {name: {"carla_frame": native_frame,
                       "raw_source": str(self.encoder.root / (name + ".mkv")) +
                       "#frame-" + str(video_index),
                       "video_frame": video_index,
                       "width": packets[name].width, "height": packets[name].height}
                for name in CAMERAS}

    def _close(self, abort):
        failure = None
        for sensor in reversed(list(self.sensors.values())):
            try:
                sensor.stop()
                sensor.destroy()
            except BaseException as exc:
                failure = failure or exc
        self.sensors = {}
        if self.encoder is not None and self.encoder.processes:
            try:
                self.encoder._finish(abort=abort or failure is not None)
            except BaseException as exc:
                failure = failure or exc
        if failure is not None:
            raise failure

    def __exit__(self, kind, value, trace):
        self._close(abort=kind is not None)
        return False

"""Spawn a source-reviewed officer performer at a surveyed junction position.

A pedestrian blueprint and costume are not proof of police authority or actual
traffic control. Those require original-camera and provenance review.
"""

from contextlib import contextmanager
import math


def _distance(a,b):
    return math.sqrt((a.x-b.x)**2+(a.y-b.y)**2+(a.z-b.z)**2)


@contextmanager
def spawn_officer_performer(world, blueprint, transform, junction_center,
                            *, min_clearance_m=2.0, max_distance_m=20.0):
    point=transform.location
    distance=_distance(point,junction_center)
    if not math.isfinite(distance) or distance<min_clearance_m or distance>max_distance_m:
        raise ValueError("Officer placement outside surveyed junction band")
    actor=world.try_spawn_actor(blueprint,transform)
    if actor is None:raise ValueError("Native officer performer spawn failed")
    try:
        realized=actor.get_location()
        if _distance(realized,point)>1.0:
            raise ValueError("Realized officer location differs from surveyed placement")
        yield {"actor":actor,"surveyed_distance_to_junction_m":distance,
               "realized_location":realized}
    finally:
        actor.destroy()

"""Per-frame officer direction program for the exact exception comparisons.

The caller supplies a Native bone-pose adapter reviewed for the selected walker.
The adapter must move the visible arm bones and report the realized pose. A
programmed direction is never substituted for an original-camera observation.
"""

from dataclasses import dataclass
import math
import re


SUFFIXES = (
    "officer_controls_go",
    "officer_controls_hold",
    "officer_present_inactive",
)
PREFIX = "testing__C157964__NRS-484B-257-2__motor_vehicle_driver__"
SWEEP_CASE = re.compile(r"testing__C157964__NRS-484B-257-2__motor_vehicle_driver__c157964_sub2_judgment_[356]-000[0-2]\Z")


def behavior_suffix(case_id):
    if isinstance(case_id, str) and case_id.startswith(PREFIX):
        suffix = case_id[len(PREFIX):]
        if suffix in SUFFIXES:
            return suffix
    if isinstance(case_id, str) and SWEEP_CASE.fullmatch(case_id):
        return "officer_controls_go"
    raise ValueError("Unknown exact subsection 2 officer case")


@dataclass(frozen=True)
class DirectionPhase:
    start_frame: int
    end_frame: int
    direction: str


def phases(case_id: str, frames: int = 600) -> tuple[DirectionPhase, ...]:
    if type(frames) is not int or frames < 3:
        raise ValueError("Officer program needs a complete 20 Hz capture")
    suffix = behavior_suffix(case_id)
    if suffix == "officer_controls_go":
        switch = frames // 2
        return (DirectionPhase(0, switch, "stop"),
                DirectionPhase(switch, frames, "go"))
    if suffix == "officer_controls_hold":
        return (DirectionPhase(0, frames, "stop"),)
    return (DirectionPhase(0, frames, "none"),)


def apply_direction(actor, adapter, case_id: str, frame_index: int,
                    frames: int = 600) -> dict:
    """Apply an explicit visible-bone pose and retain its Native readback.

    ``adapter`` takes (actor, direction) and returns a source-shaped readback
    with the same actor ID, pose name and at least one realized bone transform.
    It must raise when the selected walker lacks the necessary Native API.
    """
    if type(frame_index) is not int or not 0 <= frame_index < frames:
        raise ValueError("Officer direction frame outside capture")
    direction = next(p.direction for p in phases(case_id, frames)
                     if p.start_frame <= frame_index < p.end_frame)
    if direction == "none":
        if actor is not None and type(getattr(actor, "id", None)) is not int:
            raise ValueError("Native officer identity missing")
        if case_id.endswith("__officer_present_inactive") and actor is None:
            raise ValueError("Inactive-officer comparison lacks the officer actor")
        return {"frame_index": frame_index, "officer_actor_id": getattr(actor, "id", None),
                "programmed_direction": "none", "pose_applied": False}
    if actor is None or type(getattr(actor, "id", None)) is not int:
        raise ValueError("Native officer identity missing")
    if adapter is None:
        raise ValueError("Native visible-bone direction adapter missing")
    readback = adapter(actor, direction)
    if (not isinstance(readback, dict) or
            readback.get("officer_actor_id") != actor.id or
            readback.get("direction") != direction or
            not isinstance(readback.get("realized_bones"), dict) or
            not readback["realized_bones"]):
        raise ValueError("Native officer direction pose readback missing")
    return {"frame_index": frame_index, "officer_actor_id": actor.id,
            "programmed_direction": direction, "pose_applied": True,
            "realized_bones": readback["realized_bones"]}


def native_bone_adapter(carla, stop_pose: dict, go_pose: dict):
    """Create the Native walker adapter from reviewed, named arm rotations.

    Pose maps use walker bone names as keys and pitch/yaw/roll degrees as values.
    The selected walker must expose those bones; unsupported walkers fail before
    capture is sealed. Bone readback proves API application, not visible pixels.
    """
    poses = {"stop": stop_pose, "go": go_pose}
    if not all(isinstance(p, dict) and p for p in poses.values()):
        raise ValueError("Both visible-direction bone poses are required")
    for pose in poses.values():
        for name, angles in pose.items():
            if (not isinstance(name, str) or not name or not isinstance(angles, dict) or
                    set(angles) != {"pitch", "yaw", "roll"}):
                raise ValueError("Named officer arm bone rotation required")
            if any(type(value) not in (int, float) or not math.isfinite(value)
                   for value in angles.values()):
                raise ValueError("Officer bone rotation must be finite")

    def bone_parts(entry):
        if hasattr(entry, "name") and hasattr(entry, "relative"):
            return entry.name, entry.relative
        if isinstance(entry, (tuple, list)) and len(entry) >= 3:
            return entry[0], entry[2]
        raise ValueError("Unsupported Native walker bone readback shape")

    def apply(actor, direction):
        if direction not in poses:
            raise ValueError("Unsupported officer direction")
        original = actor.get_bones()
        available = {bone_parts(entry)[0] for entry in original.bone_transforms}
        missing = set(poses[direction]) - available
        if missing:
            raise ValueError("Selected walker lacks officer arm bones: " + ", ".join(sorted(missing)))
        updates = [(name, carla.Transform(rotation=carla.Rotation(**angles)))
                   for name, angles in poses[direction].items()]
        actor.set_bones(carla.WalkerBoneControl(updates))
        actor.blend_pose(1.0)
        readback = {name: relative.rotation
                    for entry in actor.get_bones().bone_transforms
                    for name, relative in [bone_parts(entry)]
                    if name in poses[direction]}
        if set(readback) != set(poses[direction]):
            raise ValueError("Native officer arm-bone readback incomplete")
        realized = {name: {axis: float(getattr(rotation, axis))
                           for axis in ("pitch", "yaw", "roll")}
                    for name, rotation in readback.items()}
        for name, target in poses[direction].items():
            if any(not math.isfinite(realized[name][axis]) or
                   abs(realized[name][axis] - target[axis]) > 2.0
                   for axis in ("pitch", "yaw", "roll")):
                raise ValueError("Native officer arm-bone pose differs from command")
        return {"officer_actor_id": actor.id, "direction": direction,
                "realized_bones": realized}

    return apply

"""Bounded ego control for the three selected officer exception constructions.

The approaching-hazard input is a reviewed source observation, never inferred
from an invented statutory distance or time threshold.
"""
import math
from officer_direction import behavior_suffix

PREFIX = 'testing__C157964__NRS-484B-257-2__motor_vehicle_driver__'
CASES = {'officer_controls_go', 'officer_controls_hold',
         'officer_present_inactive'}


def command(case_id, direction, *, other_inside, approaching_hazard,
            current_speed_mps, target_speed_mps=5.0):
    suffix = behavior_suffix(case_id)
    if type(other_inside) is not bool or type(approaching_hazard) is not bool:
        raise ValueError('Original other-body and approaching-hazard source required')
    for name, value in (('current speed', current_speed_mps),
                        ('target speed', target_speed_mps)):
        if type(value) not in (int, float) or not math.isfinite(value) or value < 0:
            raise ValueError('Finite ' + name + ' required')
    if suffix == 'officer_controls_go':
        if direction not in ('stop', 'go'):
            raise ValueError('Active officer direction readback required')
        proceed = direction == 'go'
    elif suffix == 'officer_controls_hold':
        if direction != 'stop':
            raise ValueError('Hold case needs stop direction readback')
        proceed = False
    else:
        if direction != 'none':
            raise ValueError('Inactive comparison must not command officer control')
        proceed = not other_inside and not approaching_hazard
    if not proceed:
        return {'throttle': 0.0, 'brake': 1.0, 'proceed': False,
                'basis': 'officer hold' if suffix != 'officer_present_inactive'
                         else 'signed entrance and sourced other traffic'}
    error = target_speed_mps - current_speed_mps
    return {'throttle': min(0.6, max(0.0, 0.25 * error)),
            'brake': min(0.6, max(0.0, -0.25 * error)), 'proceed': True,
            'basis': 'programmed officer go' if suffix == 'officer_controls_go'
                     else 'signed entrance clear on supplied observation'}


def apply_native(carla, ego, selected):
    if not isinstance(selected, dict) or set(('throttle', 'brake', 'proceed')) - set(selected):
        raise ValueError('Selected ego command incomplete')
    control = carla.VehicleControl(throttle=selected['throttle'],
                                   brake=selected['brake'])
    ego.apply_control(control)
    return {'actor_id': ego.id, 'command': selected, 'native_control_applied': True}

"""Retain Native actor geometry and four camera identities at each tick.

These are original simulator readbacks, not camera-visible direction or a
legal control judgment. A later reviewer must bind independent observations.
"""

import math

from officer_camera import CAMERAS


def _finite(value, label):
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError("Finite Native " + label + " required")
    return float(value)


def _body(actor, label):
    if type(getattr(actor, "id", None)) is not int:
        raise ValueError("Native " + label + " identity required")
    box = getattr(actor, "bounding_box", None)
    if box is None or not hasattr(box, "get_world_vertices"):
        raise ValueError("Native " + label + " bounding box required")
    vertices = box.get_world_vertices(actor.get_transform())
    if not isinstance(vertices, (tuple, list)) or len(vertices) < 4:
        raise ValueError("Complete Native " + label + " body required")
    points = [[_finite(vertex.x, label + " x"), _finite(vertex.y, label + " y")]
              for vertex in vertices]
    velocity = actor.get_velocity()
    speed = math.sqrt(sum(_finite(getattr(velocity, axis), label + " velocity") ** 2
                          for axis in ("x", "y", "z")))
    return {"actor_id": actor.id, "body_vertices_xy_m": points,
            "speed_mps": speed}


def record(world, ego, other, frame_row):
    if not isinstance(frame_row, dict) or type(frame_row.get("carla_frame")) is not int:
        raise ValueError("Native frame receipt required")
    snapshot = world.get_snapshot()
    frame = getattr(snapshot, "frame", None)
    time_s = _finite(getattr(getattr(snapshot, "timestamp", None),
                             "elapsed_seconds", None), "snapshot time")
    if frame != frame_row["carla_frame"]:
        raise ValueError("Native snapshot differs from camera frame")
    cameras = frame_row.get("camera_raw_sources")
    if not isinstance(cameras, dict) or set(cameras) != set(CAMERAS):
        raise ValueError("Four original camera frame sources required")
    for name in CAMERAS:
        if cameras[name].get("carla_frame") != frame or not cameras[name].get("raw_source"):
            raise ValueError("Original camera frame source differs: " + name)
    officer = frame_row.get("officer_program")
    if (not isinstance(officer, dict) or
            officer.get("frame_index") != frame_row.get("frame_index")):
        raise ValueError("Programmed officer pose differs from Native frame")
    return {"frame": frame, "time_s": time_s,
            "ego": _body(ego, "ego"), "other": _body(other, "other"),
            "officer_actor_id": officer.get("officer_actor_id"),
            "programmed_direction": officer.get("programmed_direction"),
            "native_pose_applied": officer.get("pose_applied"),
            "camera_frames": {name: cameras[name]["carla_frame"] for name in CAMERAS},
            "camera_raw_sources": {name: cameras[name]["raw_source"] for name in CAMERAS},
            "officer_direction_observed": "unreviewed",
            "actual_police_control_observed": "unreviewed"}

"""Check source bindings before the officer exception can enter a Native run.

This checks review provenance and consistency. It does not decide police
authority, legal control, or immediate hazard from a performer blueprint.
"""

import hashlib
import json
import math
from pathlib import Path
from shapely.geometry import Polygon


def _source(root, binding, label):
    if not isinstance(binding, dict) or set(binding) != {"path", "sha256"}:
        raise ValueError("Missing source binding: " + label)
    path = binding["path"]
    if not isinstance(path, str) or not path or Path(path).is_absolute() or ".." in Path(path).parts:
        raise ValueError("Unsafe source path: " + label)
    target = (root / path).resolve()
    if not target.is_relative_to(root.resolve()) or not target.is_file():
        raise ValueError("Missing source file: " + label)
    if hashlib.sha256(target.read_bytes()).hexdigest() != binding["sha256"]:
        raise ValueError("Changed source file: " + label)
    return target


def validate(root, packet):
    """Return a source inventory only after explicit reviews agree on site ID."""
    root = Path(root).resolve()
    if packet.get("format") != "worker-officer-subsection-2-source-review":
        raise ValueError("Wrong officer source review format")
    site = packet.get("site_id")
    if not isinstance(site, str) or not site:
        raise ValueError("Missing reviewed site identity")
    bindings = packet.get("sources")
    if not isinstance(bindings, dict):
        raise ValueError("Missing officer source inventory")
    required = ("road", "sign_inventory", "officer_authority", "officer_control",
                "other_route", "camera_sight_review")
    paths = {key: _source(root, bindings.get(key), key) for key in required}
    review = packet.get("review")
    if not isinstance(review, dict) or review.get("site_id") != site:
        raise ValueError("Source review site mismatch")
    if review.get("non_through_highway") is not True:
        raise ValueError("Non-through status lacks source review")
    entrances = review.get("entrances")
    if not isinstance(entrances, list) or len(entrances) < 2:
        raise ValueError("Incomplete all-entrance sign review")
    ids = [e.get("entrance_id") for e in entrances if isinstance(e, dict)]
    if len(ids) != len(entrances) or any(not isinstance(i, str) or not i for i in ids) or len(set(ids)) != len(ids):
        raise ValueError("Invalid reviewed entrance identities")
    for entrance in entrances:
        if entrance.get("device") not in ("stop", "yield", "none") or entrance.get("sign_visible") is not True:
            raise ValueError("Incomplete entrance device and sight review")
    ego = review.get("ego_entrance_id")
    other = review.get("other_entrance_id")
    indexed = {e["entrance_id"]: e for e in entrances}
    if ego not in indexed or indexed[ego]["device"] not in ("stop", "yield"):
        raise ValueError("Signed ego entrance not reviewed")
    if other not in indexed or other == ego or indexed[other]["device"] != "none":
        raise ValueError("Non-obligated other entrance not reviewed")
    if review.get("officer_authority_reviewed") is not True:
        raise ValueError("Police authority source review required")
    if review.get("officer_control_reviewed") is not True:
        raise ValueError("Actual officer control source review required")
    if review.get("original_camera_sight_reviewed") is not True:
        raise ValueError("Original camera sight review required")
    points = review.get("intersection_polygon_xy_m")
    if (not isinstance(points, list) or len(points) < 3 or
            any(not isinstance(point, list) or len(point) != 2 or
                any(type(value) not in (float, int) or not math.isfinite(value)
                    for value in point)
                for point in points)):
        raise ValueError("Reviewed intersection polygon required")
    polygon = Polygon(points)
    if not polygon.is_valid or polygon.area <= 0:
        raise ValueError("Invalid reviewed intersection polygon")
    return {"format": "worker-officer-subsection-2-source-intake",
            "site_id": site, "source_paths": {key: str(path.relative_to(root)) for key, path in paths.items()},
            "ego_entrance_id": ego, "other_entrance_id": other,
            "intersection_polygon_xy_m": points,
            "legal_exception_judgment": "unresolved",
            "immediate_hazard_judgment": "unresolved"}


def load_and_validate(root, packet_path):
    path = Path(packet_path)
    return validate(root, json.loads(path.read_text()))

"""Original-frame officer-control observations for the statutory exception.

Camera-visible direction and timing are evidence; legal police authority and
whether traffic was actually controlled remain source-review judgments.
"""

import hashlib
import json
import math
from pathlib import Path

from shapely.geometry import MultiPoint, Polygon


REQUIRED=("officer_context.json","officer_history.jsonl","video_frames.jsonl")


def _number(value,label):
    if isinstance(value,bool) or not isinstance(value,(int,float)) or not math.isfinite(value):
        raise ValueError("Missing finite "+label)
    return float(value)


def _rows(path):
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def analyze(root:Path)->dict:
    root=Path(root);hashes={}
    for name in REQUIRED:
        path=root/name
        if not path.is_file():raise ValueError("Missing original source: "+name)
        hashes[name]=hashlib.sha256(path.read_bytes()).hexdigest()
    ctx=json.loads((root/"officer_context.json").read_text())
    for key in ("native_map_id","intersection_id","officer_actor_id",
                "authority_source","uniform_video_source","direction_video_source",
                "junction_source","ego_route_source","sign_inventory_source",
                "other_entrance_source","highway_status_source"):
        if not ctx.get(key):raise ValueError("Missing sourced officer context: "+key)
    if ctx.get("non_through_highway") is not True or ctx.get("ego_entrance_device") not in ("stop","yield"):
        raise ValueError("Signed non-through entrance not sourced")
    if ctx.get("other_entrance_device") in ("stop","yield",None):
        raise ValueError("Non-obligated other entrance not sourced")
    polygon=Polygon(ctx.get("intersection_polygon_xy_m",[]))
    if not polygon.is_valid or polygon.area<=0:raise ValueError("Invalid intersection polygon")
    rows,frames=_rows(root/"officer_history.jsonl"),_rows(root/"video_frames.jsonl")
    if len(rows)<3 or len(rows)!=len(frames):raise ValueError("Incomplete officer/ego history")
    previous=(-1,-math.inf);samples=[];first_entry=None
    for i,(row,frame) in enumerate(zip(rows,frames)):
        fid,time=row.get("frame"),_number(row.get("time_s"),"time")
        if type(fid) is not int or fid<=previous[0] or time<=previous[1]:
            raise ValueError("Nonmonotone original history")
        previous=fid,time
        if frame.get("video_frame")!=i or frame.get("carla_frame")!=fid or frame.get("time_s")!=time:
            raise ValueError("Original frame join failed")
        if row.get("officer_actor_id")!=ctx["officer_actor_id"]:
            raise ValueError("Officer actor identity mismatch")
        instruction=row.get("officer_direction_observed")
        if instruction not in ("stop","go","unclear","none"):
            raise ValueError("Missing original officer direction observation")
        source=row.get("direction_frame_source")
        if not source:raise ValueError("Missing direction video frame source")
        controlled=row.get("traffic_control_observed")
        if type(controlled) is not bool:raise ValueError("Missing original control observation")
        approaching=row.get("other_approaching_observed")
        if type(approaching) is not bool or not row.get("other_frame_source"):
            raise ValueError("Missing original approaching-vehicle review")
        ego=row.get("ego")
        if not isinstance(ego,dict):raise ValueError("Missing ego source")
        speed=_number(ego.get("speed_mps"),"ego speed")
        if speed<0:raise ValueError("Negative ego speed")
        vertices=ego.get("body_vertices_xy_m")
        if not isinstance(vertices,list) or len(vertices)<4:raise ValueError("Missing complete ego body")
        body=MultiPoint([(_number(p[0],"body x"),_number(p[1],"body y")) for p in vertices]).convex_hull
        inside=body.intersects(polygon)
        other_vertices=row.get("other_body_vertices_xy_m")
        if not isinstance(other_vertices,list) or len(other_vertices)<4:raise ValueError("Missing other vehicle body")
        other=MultiPoint([(_number(p[0],"other x"),_number(p[1],"other y")) for p in other_vertices]).convex_hull
        other_inside=other.intersects(polygon)
        if i==0 and inside:raise ValueError("Missing pre-entry approach")
        if inside and first_entry is None:first_entry={"frame":fid,"time_s":time,
                                                       "officer_direction_observed":instruction,
                                                       "traffic_control_observed":controlled}
        samples.append({"frame":fid,"time_s":time,"direction":instruction,
                        "traffic_control_observed":controlled,"ego_speed_mps":speed,
                        "ego_body_in_intersection":inside,"other_body_in_intersection":other_inside,
                        "other_approaching_observed":approaching})
    first_hold=next(({"frame":s["frame"],"time_s":s["time_s"],
                      "officer_direction_observed":s["direction"],
                      "traffic_control_observed":s["traffic_control_observed"]}
                     for s in samples if s["other_body_in_intersection"] and
                     not s["ego_body_in_intersection"] and
                     s["traffic_control_observed"] and s["direction"]=="stop"),None)
    if first_entry is None and not (str(ctx.get("case_id","")).endswith("__officer_controls_hold") and first_hold):
        raise ValueError("No observed ego entry or sourced officer hold")
    return {"format":"worker-officer-control-exception-observations","sources":hashes,
            "first_ego_entry":first_entry,"first_hold_observation":first_hold,
            "officer_control_observed_at_entry":first_entry["traffic_control_observed"] if first_entry else None,
            "other_inside_at_ego_entry":next((s["other_body_in_intersection"] for s in samples if first_entry and s["frame"]==first_entry["frame"]),None),
            "other_approaching_observed_at_ego_entry":next((s["other_approaching_observed"] for s in samples if first_entry and s["frame"]==first_entry["frame"]),None),
            "subsection_2_applicability":("officer_hold_no_entry_candidate" if first_entry is None else
                                          "officer_control_exception_candidate" if first_entry["traffic_control_observed"] else "signed_entrance_candidate"),
            "samples":samples,"police_authority_judgment":"unresolved pending source review",
            "legal_control_exception_judgment":"unresolved","legal_conclusion":"unresolved"}

